/* index1-6 generated by prototypes/index1-6/build.cjs */
/* Alpine terrain dials (index1-6-alpine, 2026-10-23).
   One flat, mutable object: numbers and '#rrggbb'. Material keys are read every frame (the terrain
   shader's uniforms are refreshed from this object before each draw); keys whose label carries ↻
   shape the baked height field and are read once, when the landscape is built (reload to apply).
   Nothing here addresses a height ring: snow, scree and plants follow slope, drainage, shelter
   and exposure; the snow line and the plant line only bias them, through broken noise. */
export const ALPINE_TERRAIN = {
  // ---- geometry (load-time ↻) ----
  erosion: 1,          // drainage erosion: gullies and V valleys carved by the water that would drain to the rivers
  ridgeSharp: .9,      // knife-edge crests on the divides the erosion leaves
  relief: 1,           // secondary spurs and ribs seeded before the erosion runs
  range: 1,            // the ridge net between the named massifs (0 = the old flat ground between cones)
  meshDetail: 1.3,     // desktop grid density (1.3 = 14-unit cells; 1 = 20; .8 = the old 24; mobile keeps 36)
  fineErosion: 1,      // the fine real-erosion layer in the geometry (gully net, serrated crests; desktop grid only)
  // ---- snow & ice ----
  snow: .8,            // snow amount (round 3: less snow — the highest crests and the high gullies keep it)
  snowLine: 560,       // where snow starts to hold (world units; broken by noise, shelter and drainage)
  snowFade: 300,       // how soft the snow line is (how far above it full cover is reached)
  snowSlope: 44,       // steepest face (degrees) that still holds snow; steeper rock stays bare
  snowGully: 1,        // how much the gullies, hollows and ledges hold snow below / beside the open slopes
  snowBright: 1,       // snow brightness
  windRipple: 1,       // wind-scoured ripples on the snow surface (close range)
  glacier: 1,          // ice and firn filling the high drainage hollows, moraine rubble along their sides
  snowColor: '#eef3f7',
  snowShade: '#8ea4bd',// blue-grey in hollows and on the shaded side of the snow
  // ---- rock ----
  rockColor: '#4f4d4a',
  rockColor2: '#655c52',// warm grey-brown mineral variety
  rockTone: 1,          // overall rock lightness
  rockDetail: 1,        // fracture normals and grain strength
  rockScale: 1,         // fracture size (larger = bigger plates)
  cliffRelief: 1,       // canyon walls: buttresses, ribs and runnels raised out of the wall (outward only)
  // 2026-10-24 rock pass (B-01..B-05): the fracture-plate mosaic on the canyon walls becomes joints that run DOWN the slope
  jointMix: 1,          // 0 = the old fracture plates exactly (also ?rock=old), 1 = steep joints, flutes and water streaks
  jointAmt: 1,          // steep joint sets: how deep and dark the cracks read
  jointDensity: 1,      // joint spacing: larger = closer together (coarse sets ~15 and ~8.5 units, fine ~3.8)
  jointSteep: .85,      // 1 = joints stand vertical, lower = they lean (still never across the slope)
  rockFlute: 1,         // buttress and groove relief in the wall's shading: broad ribs and runnels stretched down the face
  rockStain: 1,         // vertical water streaks and rock varnish on the walls
  rockStainColor: '#3a332c',   // the varnish colour
  wetMatte: 1,          // rock at the wall foot and the shore stones: 1 = matte stone, 0 = the old satin sheen (foil-like glints)
  gully: 1,             // fall-line gullies and ribs in the shading (follow the slope, never contours)
  erosionShade: 1,      // the real eroded terrain's gullies and ribs in the shading, seen from the air
  scree: 1,             // talus aprons under the cliffs
  screeColor: '#77726a',
  // ---- low valley ----
  // ---- alpine meadows (photo texture: Poly Haven "aerial_grass_rock", CC0) ----
  grass: .88,           // meadow amount (was 1; 2026-10-24 client: 「草地再少一點點」)
  grassSlope: 42,       // steepest slope (degrees) that still carries grass; it thins before that
  grassRange: .7,      // how far up the LOCAL relief grass climbs (0 = valley floor, 1 = crest line)
  grassPatch: .8,        // how broken the meadows are (0 = a carpet, 2 = scattered patches)
  grassColor: '#9d9a5e',      // grass in sun: dry olive / green-gold
  grassShadeColor: '#55664a', // grass in shade and on the valley floor: cooler
  grassScale: 1,        // photo texture scale (1 = 7 and 31 units, two turned layers)
  grassDetail: 1,       // photo colour detail and normal-map strength
  canyonGrass: 1.4,       // canyon flight: turf on the wall tops, benches, toe slopes and rims seen from the river
  canyonGrassSlope: 60, // canyon: steepest broad slope (degrees) that carries turf
  tuftAmount: .9,       // canyon flight: 3D grass clumps standing on the turf (0 = none; they only grow where the turf is)
  tuftHeight: 2,      // clump height (world units; the camera rides 2.4 above the water)
  tuftVariation: 1,     // how much the clumps differ in size
  tuftDry: .4,          // share of dry straw blades (0 = all green, 1 = all dry)
  tuftWind: 1,          // wind sway (reduced motion: still)
  ledgeGrass: 1,        // canyon: tufts on the upward-facing ledges inside the walls (never streaks down sheer rock)
  riverMoss: 1,         // canyon: dark damp moss on the rock just above the water line
  mossColor: '#4b4a2e', // moss near the water: dark brown-green (its brightness follows the rock's)
  forest: 1,            // dark forest / scrub patches on the valley floors and sheltered low slopes
  forestColor: '#27311f',
  plantLine: 300,       // where the forest thins out (broken by noise and aspect, not a level line)
  // ---- valley tonal layers (by place in the LOCAL relief: valley floor → crest; never a height band) ----
  valleyTone: 1,        // how strongly the valley floor / mid-slope / upper-slope colours apply
  valleyShadow: 1.15,   // darkening deep in the valleys and below the surrounding ground
  valleyContrast: 1.35, // how far apart the three layers are (0 = all neutral)
  valleyReach: 1,       // how high the valley-floor tone climbs (larger = higher)
  valleyBlend: 1,       // how fast one layer turns into the next (larger = sharper)
  valleyFloorColor: '#5e666e', // valley floors and lower slopes: darker, cooler ('#808080' = no change)
  valleyMidColor: '#7f7c78',   // mid slopes
  valleyUpperColor: '#9a948b'  // upper slopes and ridges: lighter, a touch warmer
};

// 2026-10-25: index1-6 meadow amount reduced by a further 30% (.88 * .70).
// Keep the alternate opening-refinement page's existing terrain defaults.
if (typeof document !== 'undefined' && document.documentElement.matches('[data-look="index1-6"]:not([data-opening-refinement])')) {
  ALPINE_TERRAIN.grass = .616;
}

// Look-dev: ?alpine={"erosion":1.4,"snowLine":300} overrides any key before the landscape is built.
try {
  const q = typeof location === 'object' ? new URLSearchParams(location.search).get('alpine') : null;
  if (q) for (const [k, v] of Object.entries(JSON.parse(q))) if (k in ALPINE_TERRAIN && typeof v === typeof ALPINE_TERRAIN[k]) ALPINE_TERRAIN[k] = v;
} catch { /* malformed override: keep the defaults */ }
// ?rock=old brings back the fracture-plate look exactly (same as jointMix 0); ?rock=new the joint look
try {
  const r = typeof location === 'object' ? new URLSearchParams(location.search).get('rock') : null;
  if (r === 'old') ALPINE_TERRAIN.jointMix = 0; else if (r === 'new') ALPINE_TERRAIN.jointMix = 1;
} catch { /* keep the default */ }

